  /**
   * Pallet `NftCredits`'s constants
   **/
  nftCredits: {
    /**
     * The parachain the credit trees are delivered to, which mints the NFTs claimed against
     * them. There is exactly one, so the runtime fixes it rather than governance registering
     * it.
     **/
    nftClaimsParaId: PolkadotParachainPrimitivesPrimitivesId;

    /**
     * Pallet index of indiv-pallet-nft-claims on [`Config::NftClaimsParaId`], used to
     * encode the `Transact` call the trees are delivered in.
     **/
    nftClaimsPalletIndex: number;

    /**
     * The maximum number of credit trees that can wait for delivery in
     * `CreditTreeDeliveryQueue`.
     *
     * One block builds at most one tree and the offchain worker drains the queue every block,
     * so this only has to cover an outage. A tree that does not fit is never queued and needs
     * [`Pallet::replay_credit_trees`], so size it well past
     * [`Config::MaxCreditTreesPerMessage`].
     **/
    maxQueuedCreditTrees: number;

    /**
     * The maximum number of credit trees carried by one XCM message.
     *
     * The nft-claims pallet's own bound must be at least this large, otherwise the batches
     * sent to it fail to decode and the trees in them never arrive.
     **/
    maxCreditTreesPerMessage: number;

    /**
     * Cooldown, in seconds, between credit tree replays.
     *
     * [`Pallet::replay_credit_trees`] is permissionless, so this is what bounds the XCMP
     * traffic it can cause.
     **/
    replayCooldownSeconds: bigint;

    /**
     * Per-tree weight surcharge for executing `receive_credit_trees` on
     * [`Config::NftClaimsParaId`], charged to the caller of
     * [`Pallet::replay_credit_trees`].
     *
     * This prices the remote work a replay causes; [`Config::ReplayCooldownSeconds`] is what
     * bounds how often one can happen. Set it to at least the per-tree cost of
     * `receive_credit_trees` in the claims chain's own generated weights, proof size
     * included.
     **/
    nftClaimsRemoteWeight: SpWeightsWeightV2Weight;

    /**
     * How long, in seconds, a tree block's [`NftClaimCreditAwards`] stay on chain past the
     * wall-clock time of its first award, which is the time its root commits to.
     *
     * Set it to the claims chain's own deadline, [`Config::ClaimsChainTreeTtl`]: awards held
     * past that prove claims the chain no longer accepts, and awards dropped before it leave
     * a mintable credit whose proof has to come from the block's events. The
     * `integrity_test` holds it to [`Pallet::root_ttl`] as an upper bound.
     **/
    awardRetentionTtl: bigint;

    /**
     * The maximum number of tree blocks [`NftClaimCreditBlocks`] keeps per claimant.
     *
     * The index is a lookup aid, not the record of what a claimant is owed, so a full list
     * drops its oldest block rather than rejecting an award. A dropped block stays mintable
     * for [`Config::AwardRetentionTtl`], its proof coming from the block's
     * [`NftClaimCreditAwards`] entry, so the claimant loses discovery through
     * [`Pallet::nft_claim_credit_roots`] and nothing else. Size it to the tree blocks a
     * claimant accumulates over [`Config::AwardRetentionTtl`] at the chain's game cadence, and
     * account for the cost: the list is read and written whole at this bound, once per
     * distinct claimant an extrinsic awards to.
     **/
    maxCreditBlocksPerClaimant: number;

    /**
     * The maximum number of tree blocks accepted in one deletion message.
     *
     * Set this at least as high as the claims pallet's `MaxTreeDeletionsPerMessage`. A message
     * above the bound fails to decode, and [`Pallet::root_ttl`] then removes the roots its
     * deletions named.
     **/
    maxTreeDeletionsPerMessage: number;

    /**
     * The claims chain's TTL for the trees this chain sends it, which is the deadline a
     * claimant is held to.
     *
     * This duplicates a constant of another runtime, as [`Config::NftClaimsPalletIndex`] does.
     * [`Pallet::root_ttl`] derives from it, so keep it in step with the claims chain's
     * `TreeTtl`.
     **/
    claimsChainTreeTtl: bigint;

    /**
     * Maximum number of roots one [`Pallet::sweep_expired_roots`] removes.
     *
     * This bounds the call's weight against the block. The offchain worker submits one call
     * per block until nothing is due.
     **/
    maxRootsPerSweep: number;

    /**
     * Maximum number of tree blocks one [`Pallet::sweep_expired_awards`] removes.
     *
     * Far below [`Config::MaxRootsPerSweep`], though both sweep the same way: a root is 56
     * bytes where a block's awards are charged at [`AWARDS_PER_TREE`] of them, so the same
     * count would cost two orders of magnitude more proof size. The `integrity_test` holds
     * the call to the block's budget, which is what really bounds this.
     **/
    maxAwardBlocksPerSweep: number;

    /**
     * Generic pallet constant
     **/
    [name: string]: any;
  };
